\label{3afirmcorel}
Given an arbitrary set (a topological space) $\Lambda$ and a (continuous) m.s.o. stochastic mapping
\(\Phi: \Lambda\rightarrow {\mathscr H}\)
the following assertions hold:
\begin{enumerate}
\item[(i)] the scalar covariance function $\gamma_{\Phi}$, the operator covariance function $\Gamma_{\Phi}$ respectively, is a complex, a $\mathscr{C}_{1}(H)$-valued respectively, positive definite (and continuous) kernel on $\Lambda$;
\item[(ii)] the space ${\mathscr H}_{(\Phi)}$ (the module ${\mathscr H}_{\Phi}$ respectively), associated to $\Phi$ is isomorph as Hilbert space, (as normal Hilbert  ${\mathcal B}(H)$-module respectively)  to the reproducing kernel Hilbert space $K_{\gamma_{\Phi}}$, (the reproducing kernel normal Hilbert ${\mathcal B}(H)$-module ${\mathscr H}_{\Gamma_{\Phi}}$ respectively);
\item[(iii)] the measurements space $G_{\Phi}$, associated to $\Phi$ is isomorph to the Hilbert space $G_{\Gamma_{\Phi}}$, having $\Gamma_{\Phi}$ as operatorial reproducing kernel. In this way the two Hilbert spaces ensure respectively the description of the ${\mathcal B}(H)$-modules ${\mathscr H}_{\Phi}, {\mathscr H}_{\Gamma_{\Phi}}$ by means of the operatorial models mentioned in (\ref{1326}), respectively (\ref{1335}).\\
    Moreover, $G_\Phi$ can be described directly in terms of the m.s.o. stochastic mapping $\Phi$ by \eqref{1337}.
\end{enumerate}

\label{thm:subordination}
If $\Phi$ and $\Psi$ are two m.s.o.s.m. having the operator covariance functions $\Gamma_{\Phi}$ and $\Gamma_{\Psi}$ respectively, and the operator cross covariance function $\Gamma_{\Phi, \Psi}$, then $\Phi$ is subordinate to $\Psi$, iff the function $K_\lambda(\cdot)=\Gamma_{\Phi, \Psi}(\lambda,\cdot)$ is in the ${\mathcal B}(H)$-module ${\mathscr H}_{\Gamma_{\Psi}}$ with $\Gamma_{\Psi}$ as reproducing kernel and
\begin{equation}
[K_{\lambda},K_{\mu}]_{{\mathscr H}_{\Gamma_{\Psi}}}=\Gamma_{\Phi}(\lambda,\mu)\,;\quad\lambda,\,\mu \in\Lambda.
\end{equation}

\label{3afirmASM}
\begin{enumerate}
\item[(i)] If $\Lambda$ is an arbitrary set (a topological space), then for any positive definite $\mathscr{C}_{1}(H)$~-~valued kernel $\Gamma$ on $\Lambda$ (continuous on $\Lambda\times \Lambda$), there exists a (continuous) multivariate second order stochastic mapping $\Phi: \Lambda\rightarrow {\mathscr H}$, which assures for $\Gamma$ a Kolmogorov factorization:
    \begin{equation}\label{eq:Kolm.fact}
    \Gamma(\lambda, \mu)=[\Phi(\lambda), \Phi(\mu)]_{{\mathscr H}}\ ;\ \lambda, \mu \in \Lambda,
    \end{equation}
    i.e. $\Gamma$ coincides with the operator covariance function $\Gamma_{\Phi}$ of $\Phi$.
\item[(ii)] If $\Phi_{1}$ and $\Phi_{2}$ are two (continuous) m.s.o. stochastic mappings on $\Lambda$ for which $\Gamma_{\Phi_{1}}=\Gamma_{\Phi_{2}}$, then $\Phi_{1}$ and $\Phi_{2}$ are gramian unitary equivalent, i.e. there exists a gramian unitary operator $\mathrm{W}:{\mathscr H}_{\Phi_{2}}\rightarrow {\mathscr H}_{\Phi_{1}}$ such that
\end{enumerate}
\begin{equation}\label{1339}
\Phi_{1}(\lambda)= \mathrm{W} \Phi_{2}(\lambda)\, , \quad \lambda\in \Lambda.
\end{equation}

(i) Let $\Gamma$ be a positive definite ${\mathscr C}_1(H)$-valued kernel on $\Lambda$ and ${\mathscr H}_\Gamma$ ($G_\Gamma$ respectively) the normal Hilbert ${\mathcal B}(H)$-module (Hilbert space respectively) reproduced by $\Gamma$, generated as in \cite{Kaki} Sec.2.4,Thm.13,pp.37 or Prop.23,pp.44, with the gramian (respectively the scalar product) defined there. Since, by Thm. 2.4., pp. 45 of \cite{Kaki}, ${\mathscr C}_2(G_\Gamma, H)$ is an operatorial model for ${\mathscr H}_\Gamma$, embedding $G_\Gamma$ into a space of the form $L^2_0(\wp)$ (see \cite{Rao1}) ${\mathscr H}_{\Gamma}$ embeds into a normal Hilbert ${\mathcal B}(H)$-module of the form $\mathscr{C}_{2}\left(L^{2}_{0}(\wp),H\right)$. \\
In this way the ${\mathscr H}_{\Gamma}$-valued function defined by
                                           
   \( \Phi(\lambda):=\Gamma(\lambda,\cdot),\  (\lambda\in \Lambda) \)
                   
gives us exactly the m.s.o. stochastic mapping we seek, since we get for any $\lambda,\mu \in \Lambda$
    \begin{equation*}
    \Gamma_{\Phi}(\lambda,\mu)=\left[\Phi(\lambda),\Phi(\mu)\right]_{{\mathscr H}}=\left[\Gamma(\lambda,\cdot),
    \Gamma(\mu,\cdot)\right]_{{\mathscr H}_{\Gamma}}=\Gamma(\lambda,\mu).
    \end{equation*}
(ii) From the hypothesis on $\Phi_1$ and $\Phi_2$ we have
    \begin{equation*}
    \left[\Phi_{1}(\lambda),\Phi_{1}(\mu)\right]_{{\mathscr H}}=\left[\Phi_{2}(\lambda),\Phi_{2}(\mu)\right]_{{\mathscr H}},\quad \lambda,\mu \in \Lambda,
    \end{equation*}
    which means that the mapping $\mathrm{W}$ defined on $\left\{\Phi_{2}(\mu), \mu\in \Lambda\right\}$ by

    \begin{equation*}
    \mathrm{W}\Phi_{2}(\mu)=\Phi_{1}(\mu)\, , \quad \mu\in \Lambda
    \end{equation*}
    preserves the gramian, is easily extended by ${\mathcal B}(H)$-linearity, still conserving the gramian and is clearly surjective between the ${\mathcal B}(H)$-modules ${\mathscr H}_{\Phi_{2}}^{0}$ and ${\mathscr H}_{\Phi_{1}}^{0}$ (see (\ref{1323})). This allows the extension of ${\mathrm W}$ by continuity to a gramian unitary operator from ${\mathscr H}_{\Phi_{2}}$ to ${\mathscr H}_{\Phi_{1}}$, satisfying (\ref{1339}).

Analogous results, formulated in a Hilbert space setting, hold for the scalar correlation mapping
\begin{equation}
\boldsymbol{M} (\Lambda,{\mathscr H})\ni\Phi\mapsto\gamma_{\Phi}\in \boldsymbol{\gamma}(\Lambda),
\end{equation}
where $\boldsymbol{\gamma}(\Lambda)$ is the set of complex valued positive definite kernels on $\Lambda$.

\label{lem:trei.unu}
Let $\Gamma$ be a ${\mathscr C}_1(H)$-valued sesquilinear kernel on ${\mathcal D}_d^m$, which is continuous on the diagonal of ${\mathcal D}_d^m\times{\mathcal D}_d^m$. Then there is an $m$-order distribution kernel $C_\Gamma$ on ${\mathbb R}^d$ such that
\begin{equation}
C_\Gamma (\varphi\otimes\psi) = \Gamma(\varphi,\bar\psi),\quad \varphi,\psi\in{\mathcal D}_d^m.
\end{equation}
Moreover, when $\Gamma$ is positive on the diagonal, then $C_\Gamma$ is a positive definite $m$-order distribution kernel.

\label{cor3.3}
If the m.s.o. random distribution fields $U^{1},\,U^{2}\in \big({\mathcal D}^{m}_{d}\big)'({\mathscr H})$ have the same operator covariance distribution, i.e. $C_{U^{1}}=C_{U^{2}}$, then there exists a gramian unitary operator $W:{\mathscr H}_{U^{1}}\rightarrow {\mathscr H}_{U^{2}}$ such that
\begin{equation}
W\,U^{1}_{\varphi}=U^{2}_{\varphi},\quad \varphi\in {\mathcal D}^{m}_{d}.
\end{equation}

\label{thm:WoldRDF}                             
For a m.s.o.r.d.f. $\{U_{\varphi}\}_{\varphi\in {\mathcal D}_d}$ taking values in ${\mathscr H}$, there exists a unique decomposition

\begin{equation}\label{426}
U_{\varphi}=U_{\varphi}^{det}+U_{\varphi}^{p}\,,\quad \varphi\in {\mathcal D}_d
\end{equation}
of $U$ such that
\begin{enumerate}
\item[(i)]$\{U_{\varphi}^{det}\}_{\varphi\in {\mathcal D}_d}$ is operator deterministic and  $\{U_{\varphi}^{p}\}_{\varphi\in {\mathcal D}_d}$ is operator purely nondeterministic,
\item[(ii)] $U^{det}$ and $U^{p}$ are operator subordinate to $U$,
\item[(iii)] $U^{det}$ and $U^{p}$ are operator uncorrelated, i.e. the operator cross covariance distribution $C_{U^{det}, U^p}$ vanishes on ${\mathcal D}_{2d}$.
\end{enumerate}
Moreover the gramian orthogonal decomposition
\begin{equation*}
{\mathscr H}_{U}={\mathscr H}_{U^{det}}\oplus {\mathscr H}_{U^{p}}
\end{equation*}
holds.

Since in normal Hilbert ${\mathcal B}(H)$-modules, any closed submodule has a gramian projection (Lemma 2, Section 2.2, pp.22 \cite{Kaki}), let $P$ be the gramian projection associated to the submodule ${\mathscr H}_{U}^{-\infty}$ and let
\begin{equation}\label{427}
U_{\varphi}^{det}=PU_{\varphi}\quad,\quad U_{\varphi}^{p}=(I-P)U_{\varphi}\,,\quad \varphi\in {\mathcal D}_d.
\end{equation}
One can verify by using standard arguments (as in \cite[Section 5.1]{Kaki}) that \eqref{427} gives us the very m.s.o.r.d.f. we seek, the uniqueness of decomposition \eqref{426} being obtained by direct reasoning.

\label{prop:incluziuni}
For the above mentioned classes of m.s.o. random distribution fields the following inclusions hold with continuous embedding
\begin{multline}\label{3.4}
{\mathcal E}^{0}_{d}({\mathscr H})\subset fosvr\,{\mathcal M}_{d}({\mathscr H})\subset fsvr\,{\mathcal M}_{d}({\mathscr H})\subset\\
\subset({\mathcal D}_{d}^{0})'({\mathscr H})\subset({\mathcal D}_{d}^{m})'({\mathscr H})\subset{\mathcal D}'_{d}({\mathscr H}).
\end{multline}

\label{prop:incluz.poz.defn}
The valued domains of the restrictions of the operator covariance distribution mapping \eqref{3.5} to the spaces from \eqref{3.4}
satisfy respectively the following inclusions
\begin{multline}\label{eq:incluz.pos.def}
pd{\mathcal E}^{0}_{2d}\big({\mathscr C}_{1}(H)\big)\subset fosvr\,\mathfrak{M}_{2d}^{pd}\big({\mathscr C}_{1}(H)\big)\subset fsvr\,\mathfrak{M}_{2d}^{pd}\big({\mathscr C}_{1}(H)\big)\subset\\\subset pd({\mathcal D}^{0}_{2d})'\big({\mathscr C}_{1}(H)\big)
\subset pd({\mathcal D}^{m}_{2d})'\big({\mathscr C}_{1}(H)\big)\subset pd({\mathcal D}_{2d})'\big({\mathscr C}_{1}(H)\big).
\end{multline}

\label{prop2.1}
Statements analogous as for the operator covariance distribution mapping \eqref{3.5} in the corollaries above, hold for the corresponding mappings
\begin{equation}\label{311}
\begin{split}
fosvr\,{\mathcal M}_{d}({\mathscr H})\ni \xi&\mapsto\tau_{\xi}\in fosvr\,\mathfrak{M}_{2d}^{pd}\big({\mathscr C}_{1}(H)\big)\\
fsvr\,{\mathcal M}_{d}({\mathscr H})\ni \xi&\mapsto\tau_{\xi}\in fsvr\,\mathfrak{M}_{2d}^{pd}\big({\mathscr C}_{1}(H)\big).
\end{split}
\end{equation}

Moreover, these operator covariance bimeasure mappings are natural extensions of the covariance function mapping
\begin{equation}\label{313}
{\mathcal E}^{0}_{d}({\mathscr H})\ni F \mapsto \Gamma_{F}\in pd {\mathcal E}^{0}_{2d}\big({\mathscr C}_{1}(H)\big),
\end{equation}
associated to classical m.s.o. random fields, as was defined in \cite[Section 4.1, pp. 148]{Kaki}.

The positive definite operator valued bimeasures from \eqref{311} and the operator covariance function of \eqref{313} satisfy
\begin{equation}\label{314}
C_{U^{\xi}}=C^{\tau_{\xi}} \ \text{ and } \
C_{U^{F}}=C^{\Gamma_{F}},
\end{equation}
respectively.

Let  $\xi\in fosvr\,{\mathcal M}_{d}({\mathscr H})$, and $U^{\xi}\in({\mathcal D}_{d}^{m})'({\mathscr H})$ given by \eqref{3.3}. Then we successively obtain for each $\varphi,\psi \in {\mathcal D}_d^m({\mathscr H})$

\begin{eqnarray*}
C_{U^{\xi}}(\varphi\otimes\overline{\psi})&=&\big[U^{\xi}\varphi,U^{\xi}\psi\big]_{{\mathscr H}}=\left[\int\limits_{\mathbb{R}^{d}}\varphi(s)d\xi(s),
\int\limits_{\mathbb{R}^{d}}\psi(t)d\xi(t)\right]_{{\mathscr H}}=\nonumber\\
&=&\int\limits_{\mathbb{R}^{d}}\int\limits_{\mathbb{R}^{d}}\varphi(s)\overline{\psi(t)} d\big(\xi\otimes\xi\big)(s,t)=\nonumber\\ &=&\int\limits_{\mathbb{R}^{d}}\int\limits_{\mathbb{R}^{d}}\varphi(s)\overline{\psi(t)} d\tau_{\xi}(s,t),             
                                                                                         
\end{eqnarray*}
which by \eqref{eq:covdistrib} gives the first relation in \eqref{314}.

In particular for $\xi=\xi^{F}$ with $\xi^{F}$ given by \eqref{3.2}, we have first $U^{\xi}=U^{F}$, given by \eqref{3.3} and secondly, for each $\varphi,\,\psi\in {\mathcal D}_{d}^{m}$

\begin{eqnarray*}
C^{\tau_{\xi^{F}}}(\varphi\otimes\overline{\psi})&=&\int\limits_{\mathbb{R}^{d}}\int\limits_{\mathbb{R}^{d}}\varphi(s)\overline{\psi(t)}\Gamma_{F}(s,t) ds dt \nonumber\\
&=& C^{\Gamma_{F}} (\varphi\otimes\overline{\psi}),
\end{eqnarray*}
which finally means the second relation from \eqref{314}.
